-- Unificacion de Pedidos, parte 5: los clientes reales pasan a
-- pedidos.cliente_config, colgando de public.clientes por RUC.
--
-- 3.402 clientes en el origen (pedidos.customers del proyecto de Andres).
-- Entran 3.399. Los 3 que quedan afuera son datos de prueba, con nombre y
-- todo:
--
--   20999999999  CLIENTE DE PRUEBA E2E              (ACTIVO)
--   99999999002  CLIENTE NUEVO DE PRUEBA (BUG FIX)  (ACTIVO)
--   123          PRUEBA                             (RECHAZADO, 3 digitos)
--
-- Los 3.399 restantes matchean TODOS contra public.clientes por RUC: cero
-- huerfanos. Eso confirma que las dos bases tenian el mismo cliente cargado
-- dos veces.
--
-- ===================================================================
-- LO QUE NO SE MIGRA, PORQUE NO HAY NADA QUE MIGRAR
-- ===================================================================
-- La cartera entera comparte tres atributos, asi que no se copian por fila:
--
--   canal                -> Horizontal para los 3.399 (los otros dos canales
--                           que aparecian en el origen eran de los clientes
--                           de prueba)
--   condicion_pago       -> null en los 3.399 (los 3 con 'Contado' eran los
--                           de prueba)
--   es_agente_retencion  -> false en los 3.399, se deja el default
--   fecha_ultima_validacion_tributaria -> null en los 3.399
--
-- El whatsapp TAMPOCO se copia, y este caso es distinto: en el origen hay 456
-- clientes con whatsapp, o sea que hay dato. No se migra porque
-- public.clientes.celular ya tiene 507 telefonos — mas completo que el origen.
-- Copiarlo dejaria dos columnas con el telefono del mismo cliente,
-- envejeciendo cada una por su lado: exactamente el problema que la
-- unificacion vino a resolver. Las pantallas de Pedidos leen
-- public.clientes.celular.
--
-- Queda pendiente decidir si pedidos.cliente_config.whatsapp se elimina: hoy
-- es una columna que no deberia usarse nunca, y una columna asi termina
-- usandose.
--
-- Los RUCs van como una cadena de bloques de 11 caracteres en vez de 3.399
-- literales: es el mismo dato, ocupa la mitad, y `substring` sobre
-- generate_series lo desarma sin ambiguedad porque el RUC peruano es siempre
-- de largo fijo.
--
-- NO se usa "todos los de public.clientes menos una lista": esa tabla crece
-- sola porque el importador de Cobranzas corre en produccion. Entre dos
-- snapshots de esta misma sesion paso de 3.447 a 3.453 filas, y el atajo
-- habria metido 6 clientes que nunca estuvieron en Pedidos.
--
-- Re-ejecutable: on conflict (cliente_ruc) actualiza.

-- Grupo 1: acepta factura o boleta, activos.
-- 1869 clientes.
insert into pedidos.cliente_config
  (cliente_ruc, canal_id, tipo_comprobante_permitido, estado)
select substring('' from n * 11 + 1 for 11),
       (select id from pedidos.sales_channels where nombre = 'Horizontal'),
       'FACTURA_O_BOLETA', 'ACTIVO'
from generate_series(0, 1868) as n
on conflict (cliente_ruc) do update set
  canal_id = excluded.canal_id,
  tipo_comprobante_permitido = excluded.tipo_comprobante_permitido,
  estado = excluded.estado,
  updated_at = now();

-- Grupo 2: solo factura, activos.
-- 1379 clientes.
insert into pedidos.cliente_config
  (cliente_ruc, canal_id, tipo_comprobante_permitido, estado)
select substring('' from n * 11 + 1 for 11),
       (select id from pedidos.sales_channels where nombre = 'Horizontal'),
       'FACTURA', 'ACTIVO'
from generate_series(0, 1378) as n
on conflict (cliente_ruc) do update set
  canal_id = excluded.canal_id,
  tipo_comprobante_permitido = excluded.tipo_comprobante_permitido,
  estado = excluded.estado,
  updated_at = now();

-- Grupo 3: solo boleta y pendientes de validacion tributaria.
-- Estos son los que Control de Pedidos todavia tiene que revisar.
-- 151 clientes.
insert into pedidos.cliente_config
  (cliente_ruc, canal_id, tipo_comprobante_permitido, estado)
select substring('' from n * 11 + 1 for 11),
       (select id from pedidos.sales_channels where nombre = 'Horizontal'),
       'BOLETA', 'PENDIENTE_DE_VALIDACION'
from generate_series(0, 150) as n
on conflict (cliente_ruc) do update set
  canal_id = excluded.canal_id,
  tipo_comprobante_permitido = excluded.tipo_comprobante_permitido,
  estado = excluded.estado,
  updated_at = now();
